using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        // GET all shipments (dispatchers only)
        group.MapGet("/", async (ApplicationDbContext db, string? status, string? search) =>
        {
            var query = db.Shipments.AsQueryable();

            if (Enum.TryParse<Data.ShipmentStatus>(status, true, out var s))
                query = query.Where(x => x.Status == s);

            if (!string.IsNullOrWhiteSpace(search))
                query = query.Where(x =>
                    x.TrackingNumber.Contains(search) ||
                    x.Destination.Contains(search) ||
                    (x.RecipientName != null && x.RecipientName.Contains(search)));

            var shipments = await query
                .OrderByDescending(x => x.CreatedAtUtc)
                .Select(x => ToDto(x))
                .ToListAsync();

            return Results.Ok(shipments);
        }).RequireAuthorization("DispatcherPolicy");

        // GET single shipment by id (dispatchers only)
        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            return shipment is null ? Results.NotFound() : Results.Ok(ToDto(shipment));
        }).RequireAuthorization("DispatcherPolicy");

        // PUT update status (dispatchers only)
        group.MapPut("/{id:int}/status", async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)request.NewStatus;
            if (request.Notes is not null)
                shipment.Notes = request.Notes;

            await db.SaveChangesAsync();
            return Results.Ok(ToDto(shipment));
        }).RequireAuthorization("DispatcherPolicy");

        // POST create shipment (dispatchers only)
        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = (Data.ShipmentStatus)(int)dto.Status,
                CreatedAtUtc = DateTime.UtcNow,
                EstimatedDeliveryUtc = dto.EstimatedDeliveryUtc,
                RecipientName = dto.RecipientName,
                CustomerEmail = dto.CustomerEmail,
                Notes = dto.Notes
            };
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", ToDto(shipment));
        }).RequireAuthorization("DispatcherPolicy");

        // Public tracking endpoint — no auth required
        app.MapGet("/api/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);

            if (shipment is null)
                return Results.Ok(new TrackingResult { Found = false });

            return Results.Ok(new TrackingResult
            {
                Found = true,
                Shipment = ToDto(shipment)
            });
        });

        // Customer shipments — returns shipments for the logged-in customer's email
        app.MapGet("/api/my-shipments", async (HttpContext ctx, ApplicationDbContext db, UserManager<ApplicationUser> userManager) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user?.Email is null) return Results.Unauthorized();

            var shipments = await db.Shipments
                .Where(x => x.CustomerEmail == user.Email)
                .OrderByDescending(x => x.CreatedAtUtc)
                .Select(x => ToDto(x))
                .ToListAsync();

            return Results.Ok(shipments);
        }).RequireAuthorization();
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (Client.Models.ShipmentStatus)(int)s.Status,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        RecipientName = s.RecipientName,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    };
}

