@inject HttpClient Http

@code {
    private List<ShipmentDto>? shipments;
    private string searchTerm = "";
    private string statusFilter = "";
    private string? error;
    private string? createError;
    private bool showCreateForm;
    private bool creating;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDelivery;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            var url = "/api/shipments?";
            if (!string.IsNullOrWhiteSpace(statusFilter))
                url += $"status={statusFilter}&";
            if (!string.IsNullOrWhiteSpace(searchTerm))
                url += $"search={Uri.EscapeDataString(searchTerm)}&";

            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>(url);
            error = null;
        }
        catch (Exception ex)
        {
            error = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task HandleSearch()
    {
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment)
    {
        try
        {
            var request = new UpdateShipmentStatusRequest { NewStatus = shipment.Status };
            var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status", request);
            response.EnsureSuccessStatusCode();
        }
        catch (Exception ex)
        {
            error = $"Failed to update status: {ex.Message}";
            await LoadShipments();
        }
    }

    private void ToggleCreateForm()
    {
        showCreateForm = !showCreateForm;
        newShipment = new();
        estimatedDelivery = null;
        createError = null;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Origin and Destination are required.";
            return;
        }

        creating = true;
        createError = null;

        try
        {
            newShipment.TrackingNumber = $"SHT-{Random.Shared.Next(100000, 999999)}";
            newShipment.EstimatedDeliveryUtc = estimatedDelivery?.ToUniversalTime();
            var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
            response.EnsureSuccessStatusCode();
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            creating = false;
        }
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h1>🔍 Track Your Shipment</h1>
<p>Enter your tracking number below to see the current status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-5">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg" placeholder="e.g. SHT-100001"
                   @bind="trackingNumber" @onkeyup="HandleKeyPress" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@tracking">
                @(tracking ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && result is not null)
{
    @if (!result.Found)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment matches tracking number <strong>@searchedNumber</strong>.
            Please check the number and try again.
        </div>
    }
    else if (result.Shipment is not null)
    {
        var s = result.Shipment;
        <div class="card">
            <div class="card-header bg-dark text-white">
                <h5 class="mb-0">Tracking: @s.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <div class="row mb-3">
                    <div class="col-md-6">
                        <h6>Status</h6>
                        <span class="badge fs-6 @GetStatusBadge(s.Status)">@FormatStatus(s.Status)</span>
                    </div>
                    <div class="col-md-6">
                        <h6>Estimated Delivery</h6>
                        <p class="fs-5">
                            @if (s.EstimatedDeliveryUtc.HasValue)
                            {
                                @s.EstimatedDeliveryUtc.Value.ToString("dddd, MMMM dd, yyyy")
                            }
                            else
                            {
                                <span class="text-muted">Not yet available</span>
                            }
                        </p>
                    </div>
                </div>

                <!-- Progress bar -->
                <div class="mb-3">
                    <h6>Shipment Progress</h6>
                    <div class="progress" style="height: 30px;">
                        <div class="progress-bar @GetProgressBarClass(s.Status)"
                             role="progressbar"
                             style="width: @(GetProgressPercent(s.Status))%"
                             aria-valuenow="@GetProgressPercent(s.Status)"
                             aria-valuemin="0" aria-valuemax="100">
                            @FormatStatus(s.Status)
                        </div>
                    </div>
                </div>

                <div class="row">
                    <div class="col-md-4">
                        <h6>📍 Origin</h6>
                        <p>@s.Origin</p>
                    </div>
                    <div class="col-md-4">
                        <h6>📍 Destination</h6>
                        <p>@s.Destination</p>
                    </div>
                    <div class="col-md-4">
                        <h6>👤 Recipient</h6>
                        <p>@(s.RecipientName ?? "—")</p>
                    </div>
                </div>

                <div class="row">
                    <div class="col-md-4">
                        <h6>📅 Shipped On</h6>
                        <p>@s.CreatedAtUtc.ToString("MMM dd, yyyy")</p>
                    </div>
                </div>
            </div>
        </div>
    }
}

@inject HttpClient Http

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private TrackingResult? result;
    private bool searched;
    private bool tracking;

    private async Task HandleKeyPress(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        tracking = true;
        searched = false;

        try
        {
            searchedNumber = trackingNumber.Trim();
            result = await Http.GetFromJsonAsync<TrackingResult>($"/api/track/{Uri.EscapeDataString(searchedNumber)}");
            searched = true;
        }
        catch
        {
            result = new TrackingResult { Found = false };
            searched = true;
        }
        finally
        {
            tracking = false;
        }
    }

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
