@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>📦 Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search tracking #, destination, recipient..."
               @bind="searchTerm" @bind:event="oninput" @onkeyup="HandleSearch" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ToggleCreateForm">
            @(showCreateForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Recipient" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-2">
                    <input type="datetime-local" class="form-control" @bind="estimatedDelivery" />
                </div>
            </div>
            <div class="mt-2">
                <button class="btn btn-success" @onclick="CreateShipment" disabled="@creating">
                    @(creating ? "Creating..." : "Create")
                </button>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in shipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.RecipientName</td>
                        <td>
                            <span class="badge @GetStatusBadge(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@shipment.EstimatedDeliveryUtc?.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                            {
                                <div class="btn-group btn-group-sm">
                                    <select class="form-select form-select-sm" style="width:auto"
                                            @bind="shipment.Status" @bind:after="() => UpdateStatus(shipment)">
                                        @foreach (var s in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@s">@s</option>
                                        }
                                    </select>
                                </div>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(error))
{
    <div class="alert alert-danger">@error</div>
}

@inject HttpClient Http

@code {
    private List<ShipmentDto>? shipments;
    private string searchTerm = "";
    private string statusFilter = "";
    private string? error;
    private string? createError;
    private bool showCreateForm;
    private bool creating;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDelivery;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            var url = "/api/shipments?";
            if (!string.IsNullOrWhiteSpace(statusFilter))
                url += $"status={statusFilter}&";
            if (!string.IsNullOrWhiteSpace(searchTerm))
                url += $"search={Uri.EscapeDataString(searchTerm)}&";

            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>(url);
            error = null;
        }
        catch (Exception ex)
        {
            error = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task HandleSearch()
    {
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment)
    {
        try
        {
            var request = new UpdateShipmentStatusRequest { NewStatus = shipment.Status };
            var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status", request);
            response.EnsureSuccessStatusCode();
        }
        catch (Exception ex)
        {
            error = $"Failed to update status: {ex.Message}";
            await LoadShipments();
        }
    }

    private void ToggleCreateForm()
    {
        showCreateForm = !showCreateForm;
        newShipment = new();
        estimatedDelivery = null;
        createError = null;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Origin and Destination are required.";
            return;
        }

        creating = true;
        createError = null;

        try
        {
            newShipment.TrackingNumber = $"SHT-{Random.Shared.Next(100000, 999999)}";
            newShipment.EstimatedDeliveryUtc = estimatedDelivery?.ToUniversalTime();
            var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
            response.EnsureSuccessStatusCode();
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            creating = false;
        }
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

